mapper.update:
UPDATE demo_order
SET order_status = 'COMPLETED',
    pay_status = 'PAY_SUCCESS',
    pay_time = #{payTime},
    updated_at = #{payTime}
WHERE order_id = #{orderId}
  AND order_status = 'SUBMIT'

    AND member_id = #{memberId}

UPDATE demo_order
SET order_status = 'CANCEL',
    pay_status = 'CLOSE',
    cancel_time = #{cancelTime},
    updated_at = #{cancelTime}
WHERE order_id = #{orderId}
  AND order_status = 'SUBMIT'

    AND member_id = #{memberId}

mapper.select:
SELECT COUNT(*)
FROM demo_order o
WHERE o.member_id = #{memberId}

    AND o.order_status = #{orderStatus}

SELECT o.*
FROM demo_order o
WHERE o.member_id = #{memberId}

    AND o.order_status = #{orderStatus}

ORDER BY o.created_at DESC
LIMIT #{offset}, #{pageSize}
